import sys
from collections import deque

def bfs(tree, start):
    dist = [-1] * (len(tree) + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def query(nodes):
    print(f"? {len(nodes)} {' '.join(map(str, nodes))}", flush=True)
    return map(int, sys.stdin.readline().split())

def find_centroid(tree, n):
    subtree_size = [0] * (n + 1)

    def dfs(node, parent):
        size = 1
        for neighbor in tree[node]:
            if neighbor != parent:
                size += dfs(neighbor, node)
        subtree_size[node] = size
        return size

    def find(node, parent, total_size):
        for neighbor in tree[node]:
            if neighbor != parent and subtree_size[neighbor] > total_size // 2:
                return find(neighbor, node, total_size)
        return node

    dfs(1, -1)
    return find(1, -1, n)

t = int(sys.stdin.readline())
for _ in range(t):
    n = int(sys.stdin.readline())
    tree = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        tree[u].append(v)
        tree[v].append(u)

    centroid = find_centroid(tree, n)
    dist_from_centroid = bfs(tree, centroid)

    _, d1 = query([centroid])
    farthest_node, _ = max(enumerate(dist_from_centroid[1:], 1), key=lambda x: x[1])
    dist_from_farthest = bfs(tree, farthest_node)
    farthest_node2, d2 = max(enumerate(dist_from_farthest[1:], 1), key=lambda x: x[1])

    if d1 == d2:
        candidate1, _ = query([farthest_node, farthest_node2])
        candidate2 = farthest_node if candidate1 == farthest_node2 else farthest_node2
    else:
        candidate1, _ = query([farthest_node, centroid])
        candidate2, _ = query([farthest_node2, centroid])

